insert into public.service_categories (slug, name, description, icon, sort_order) values ('surgery', 'Surgery & Procedures', 'Our surgical suite is equipped for everything from routine sterilizations to complex soft-tissue and emergency procedures, with full pre-anaesthetic screening and dedicated post-op monitoring for every patient.', 'Scissors', 0);
insert into public.service_categories (slug, name, description, icon, sort_order) values ('preventive-care', 'Primary & Preventive Care', 'The foundation of a long, healthy life — core and lifestyle vaccinations, wellness exams, parasite prevention, microchipping, and health certificates for travel or breed registration.', 'ShieldPlus', 1);
insert into public.service_categories (slug, name, description, icon, sort_order) values ('dental', 'Dental Services', 'Dental disease affects most pets by age three. We offer ultrasonic scaling and polishing, full-mouth dental radiographs, and extractions under monitored anaesthesia.', 'Sparkles', 2);
insert into public.service_categories (slug, name, description, icon, sort_order) values ('diagnostics', 'Laboratory & Diagnostics', 'Our in-house lab returns most bloodwork and urinalysis results within the hour, so treatment decisions don''t wait on a courier.', 'FlaskConical', 3);
insert into public.service_categories (slug, name, description, icon, sort_order) values ('imaging', 'Imaging', 'Digital X-ray and ultrasound equipment on site means faster, clearer answers for injuries, swallowed objects, and internal medicine cases — no referral wait.', 'ScanLine', 4);
insert into public.service_categories (slug, name, description, icon, sort_order) values ('orthopedics', 'Orthopedics', 'From cranial cruciate ligament injuries to fracture stabilization and spinal cases, our orthopedic service pairs surgical expertise with a structured rehab plan.', 'Bone', 5);
insert into public.service_categories (slug, name, description, icon, sort_order) values ('endoscopy', 'Endoscopy', 'Bronchoscopy and gastroscopy let us investigate chronic coughing, swallowing difficulty, or a suspected foreign body without open surgery in many cases.', 'Search', 6);
insert into public.service_categories (slug, name, description, icon, sort_order) values ('emergency', 'Emergency Care', 'Accidents don''t wait for an appointment. We prioritize acute cases for same-day stabilization and treatment, with an after-hours line for existing clients.', 'Siren', 7);
insert into public.services (category_id, slug, name, description, price_from, price_to, duration_minutes) select id, 'spay-neuter', 'Spay / Neuter', 'Routine sterilization with pre-anaesthetic bloodwork and take-home pain plan.', 220, 420, 90 from public.service_categories where slug = 'surgery';
